\dfrac{U_D-U_F}{r} & \text{f"ur} U_D \geq U_F \end{cases}
\]

\subsubsection*{Ersatzschaltung für die Diode:}
\begin{minipage}[t]{0.45\textwidth}
$ \underline{U_D < U_F}$	

\rBild{scale=1.41}{_w_7}

\end{minipage}
\begin{minipage}[t]{0.45\textwidth}
$ \underline{U_D \geq U_F}$	

\rBild{scale=1.41}{_w_6}

\end{minipage}

\subsubsection*{Schaltung 1:}
\begin{minipage}[t]{0.45\textwidth}

\rBild{scale=1.41}{_w_3a}

\[
\underline{I=\dfrac{U}{R_2}}
\]
für $\underline{U=U_D < U_F}$
\end{minipage}
\begin{minipage}[t]{0.45\textwidth}

\rBild{scale=1.41}{_w_3}

\[
I=\dfrac{U}{R_2}+\dfrac{U-U_F}{r+R_1}
\]
\[
\underline{I=\left(\dfrac{1}{R_2}+\dfrac{1}{r+R_1}\right) U -\dfrac{U_F}{r+R_1}}
\]
für
\[
U_D=U_F+r\cdot\dfrac{U-U_F}{r+R_1} \geq U_F
\]
\[
\underline{U \geq U_F}
\]
\end{minipage}

\subsubsection*{Schaltung 2:}
\begin{minipage}[t]{0.45\textwidth}

\rBild{scale=1.41}{_w_4a}

\[
\underline{I=\dfrac{U}{R_1+R_2}}
\]
für 
\[
U_D = \dfrac{R_2}{R_1+R_2} U < U_F
\]
\[
\underline{U < \left(1+\dfrac{R_1}{R_2}\right) U_F = 0,715\mathrm{V}}
\]
\end{minipage}
\begin{minipage}[t]{0.45\textwidth}

\rBild{scale=1.41}{_w_4}

\begin{align*}
(1) & &	I&=\dfrac{U_D}{R_2}+\dfrac{U_D-U_F}{r} 

(2) & &	U&=U_D+R_1 I \Rightarrow U_D= U-R_1 I
\end{align*}
\[
I=\dfrac{U}{R_2}-\dfrac{R_1}{R_2} I + \dfrac{U-U_F}{r} - \dfrac{R_1}{r} I
\]
\[
I=\dfrac{\frac{U}{R_2}+\frac{U-U_F}{r}}{1+\frac{R_1}{R_2}+\frac{R_1}{r}}
\]
\[
\underline{I=\dfrac{\left(R_2+r \right)U - R_2 U_F}{\left(R_2+r \right)R_1 + R_2 r}}
\]
für
\[
U\overset{(1), (2)}{\ = \ }U_D+\dfrac{R_1}{R_2} U_D+\dfrac{R_1}{r} (U_D-U_F)
\]
\[
U=U_D\left(1+\dfrac{R_1}{R_2}+\dfrac{R_1}{r}\right)-\dfrac{R_1}{r} U_F
\]
\[
U_D \geq U_F
\]
\[
\Rightarrow U \geq U_F \left(1+\dfrac{R_1}{R_2}+\dfrac{R_1}{r}\right)-\dfrac{R_1}{r} U_F
\]
\[
\underline{U \geq \left(1+\dfrac{R_1}{R_2}\right) U_F}
\]
\end{minipage}

